'use strict'

const { Transform } = require('node:stream')

function split (convertLine) {
  let partialLine = ''
  return new Transform({
    autoDestroy: true,
    readableObjectMode: true, // means it produced objects
    transform (chunk, _enc, next) {
      const str = partialLine + chunk.toString()
      let start = 0
      let idx
      while (~(idx = str.indexOf('\n', start))) {
        const err = processLine(this, str.substring(start, idx), convertLine)
        if (err) return next(err)
        start = idx + 1
      }
      partialLine = str.substring(start)
      next()
    },
    flush (done) {
      const err = processLine(this, partialLine ? partialLine.trim() : partialLine, convertLine)
      err ? done(err) : done()
    },
  })
}

function processLine (readable, line, convertLine) {
  try {
    const value = line ? convertLine.call(readable, line) : undefined
    if (value !== undefined) readable.push(value)
  } catch (err) {
    return err
  }
}

module.exports = split
